import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Plugin packaging, signing and registries","description":"","frontmatter":{"title":"Plugin packaging, signing and registries","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4621be5493f2518bff00b4330fcf781ac016761ed8549c118515d6c212fc56cf","translationRevision":"4621be5493f2518bff00b4330fcf781ac016761ed8549c118515d6c212fc56cf","order":280},"headers":[],"relativePath":"en/developer/plugins/packaging-registry.md","filePath":"en/developer/plugins/packaging-registry.md","lastUpdated":1795731074000}`),a={name:`en/developer/plugins/packaging-registry.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Plugin packaging, signing and registries <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to “Plugin packaging, signing and registries”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Distribute a package whose bytes, publisher authority and host compatibility can be checked independently. Start with a validated plugin and a supported target. Signing needs private author keys kept outside the repository; registry root delegation is a separate operator responsibility.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Prepare a reviewable archive <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to “Prepare a reviewable archive”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compiles the package and creates <code>.plugin</code> archives. Manifest entry, assets, locales, UI output and relevant runtime dependencies are included with <code>checksums.json</code>. Native/process builds need a compatible target artifact; JavaScript-only packages remain portable until native addons or platform facilities constrain them.</p><p>For an existing built archive, use exact file paths rather than an unreviewed wildcard:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Replace the archive name with the build&#39;s actual target-specific output. The signature covers checksums, which cover package files. Public keys can be shared; private key files must not enter source control or logs.</p><h2 id="trust-and-update-policy" tabindex="-1">Trust and update policy <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to “Trust and update policy”">​</a></h2><p>The static registry protocol has root-signed authority and delegated index/publisher keys. Publisher namespace approval is not the same as package integrity, and a Cloud catalog digest cannot replace either signature chain. The resolver checks channel, engine, schema/protocol/ABI, runtime and target. Yanked, revoked or incompatible releases remain ineligible even when their file hash matches.</p><p>Host installation first presents a review. Automatic updates require permitted policy, an unpinned package, compatible signed publisher and no new authority; expanded permissions require review. Product Cloud catalog installation is distinct from low-level static registry authoring, and ordinary product flows reject arbitrary remote package URLs.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Expected result, recovery and verification <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to “Expected result, recovery and verification”">​</a></h2><p>The installer can verify bytes before applying a reviewed package and retain rollback/recovery state. Development staging is outside installer management. On a trust failure, repair delegation or publisher metadata rather than use unsigned override flags as normal distribution policy. On uncertain runtime startup, stop replacement and reconcile its retained outcome.</p><p>Use <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> and the registry tests for offline fixtures. The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">package verifier</a> and <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">registry model</a> own the technical formats; publishing infrastructure needs separate operator acceptance.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>Treat verification JSON as the result, not just the process exit code. <code>verify</code> can exit successfully with <code>signature.status</code> equal to <code>unsigned</code> or <code>untrusted</code>. Accept only <code>verified</code> with the expected package ID, publisher and key ID, then check your distribution policy. A locally supplied <code>--trust</code> key proves that local signature relationship, not registry delegation or namespace approval. Checksums alone prove neither publisher authority nor updater trust. Example automation below must fail on any unexpected result.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div><h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>list publisher namespaces</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>create a publisher namespace</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>delete a namespace or publisher <strong>destructive</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>list signing keys of a publisher</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>enroll a publisher key; reads the backend password from stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>upload a plugin package</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>submit an upload for review</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>create a release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publish a release</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>list configured registries</td></tr><tr><td><code>tiktools registry refresh</code></td><td>refresh registry metadata</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>show one registry package</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>search the cloud catalog</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>cloud catalog summaries page</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versions of one cloud catalog package</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>pagination capabilities of the cloud catalog</td></tr><tr><td><code>tiktools registry defaults</code></td><td>default registry configuration</td></tr></tbody></table><p>See the <a href="./../cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};